class Solution {
    static String reverseWords(String s) {
        String[] parts = s.split(" ");
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) out.append(' ');
            out.append(new StringBuilder(parts[i]).reverse());
        }
        return out.toString();
    }
}

