import java.util.*;

class Solution {
    static int[] dedupe(int[] a) {
        LinkedHashSet<Integer> set = new LinkedHashSet<>();
        for (int v : a) set.add(v);
        int[] out = new int[set.size()];
        int i = 0;
        for (int v : set) out[i++] = v;
        return out;
    }
}

