class Box implements Serializable { int v = 5; transient int hidden = 9; }

class Solution {
    static int hiddenAfterRoundTrip() throws Exception {
        Path p = Path.of("box.ser");
        try (ObjectOutputStream oos = new ObjectOutputStream(Files.newOutputStream(p))) { oos.writeObject(new Box()); }
        try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(p))) { return ((Box) ois.readObject()).hidden; }
    }
}

