import java.util.concurrent.*;

class Solution {
    static long sumAsync(int n) throws Exception {
        ExecutorService es = Executors.newSingleThreadExecutor();
        Future<Long> f = es.submit(() -> { long s = 0; for (int i = 1; i <= n; i++) s += i; return s; });
        long r = f.get();
        es.shutdown();
        return r;
    }
}

